mapper.select:
SELECT password_hash
FROM public.auth_password_history
WHERE subject_type = #{subjectType}
  AND subject_id = #{subjectId}
  AND is_deleted = false
ORDER BY changed_time DESC, id DESC
LIMIT #{limit}

mapper.insert:
INSERT INTO public.auth_password_history (
    subject_type, subject_id, password_hash, algorithm, changed_time, created_by, updated_by
)
SELECT subject_type, subject_id, password_hash, algorithm,
       COALESCE(password_changed_at, CURRENT_TIMESTAMP), #{subjectId}, #{subjectId}
FROM public.auth_credential
WHERE subject_type = #{subjectType}
  AND subject_id = #{subjectId}
  AND password_hash IS NOT NULL
  AND algorithm IS NOT NULL
  AND is_deleted = false
